export const SWISS_LOCATIONS = Array.from(
  new Set(SWISS_POSTAL_LOCATIONS.map((location) => location.name))
).sort((a, b) => a.localeCompare(b, "de-CH"));

export const SWISS_POSTAL_LOCATION_COUNT =
  SWISS_POSTAL_LOCATIONS.length;

export function findSwissPostalLocationsByZip(
  zip: string
): SwissPostalLocation[] {
  const normalizedZip = zip.trim();

  return SWISS_POSTAL_LOCATIONS.filter(
    (location) => location.zip === normalizedZip
  );
}

export function findSwissPostalLocationsByName(
  name: string
): SwissPostalLocation[] {
  const normalizedName = name.trim().toLocaleLowerCase("de-CH");

  if (!normalizedName) {
    return [];
  }

  return SWISS_POSTAL_LOCATIONS.filter((location) =>
    location.name.toLocaleLowerCase("de-CH").includes(normalizedName)
  );
}

